// Presentation helpers read the real models; no simulation/scoring changes.
export function gravityMission(w){if(w.mode==='survival')return `Survive ${Math.max(0,(w.duration-w.clock)/1000).toFixed(1)}s · ${w.lives} lives · chaos waves ignore safety`;const required=w.level.orbs.filter(o=>o.required),left=required.filter(o=>!w.collected.has(o.id)).length;return w.goalOpen?'Goal powered · guide the ball into the mint ring':`${left?left+' gold orb'+(left===1?'':'s')+' remaining':'Gold orbs collected'}${w.level.requiredSwitch&&!w.switches.has(w.level.requiredSwitch)?' · activate switch '+w.level.requiredSwitch:''}`;}
export function slingFeedback(pull,inFlight,projectile){if(inFlight)return 'Watch the chain reaction. Next Shot skips waiting.';if(pull){const power=Math.min(100,Math.round(Math.hypot(pull.x,pull.y)/125*100));return power<10?'Pull farther to launch · release to fire, cancel to keep your shot':`${power}% power · launch opposite your pull · release to fire`;}return projectile.help;}
export function drawGravityScenery(c,theme){c.save();c.strokeStyle='#8db2ba24';c.lineWidth=3;for(const x of [65,935]){c.beginPath();c.moveTo(x,65);c.lineTo(x,575);c.stroke();for(let y=85;y<580;y+=80){c.strokeRect(x-15,y,30,42);c.fillStyle='#b9c7ae22';c.fillRect(x-9,y+7,18,5);}}c.strokeStyle='#b4c8ba16';c.lineWidth=12;c.beginPath();c.ellipse(500,320,360,235,0,0,Math.PI*2);c.stroke();c.lineWidth=2;c.strokeStyle='#b4c8ba22';c.beginPath();c.ellipse(500,320,383,252,0,0,Math.PI*2);c.stroke();c.fillStyle='#192d37';c.fillRect(385,7,230,36);c.fillStyle='#b8cdc3';c.font='600 12px Outfit, sans-serif';c.textAlign='center';c.fillText('ORBIT WORKSHOP · '+theme.toUpperCase(),500,30);c.restore();}
export function drawEnergyBall(c,p,r,angle=0){c.save();c.translate(p.x,p.y);const g=c.createRadialGradient(-r*.3,-r*.4,1,0,0,r);g.addColorStop(0,'#f1f7e6');g.addColorStop(.45,'#a2d9d1');g.addColorStop(1,'#507b93');c.fillStyle=g;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.rotate(angle);c.strokeStyle='#233e51';c.lineWidth=2;c.beginPath();c.ellipse(0,0,r*.45,r*.84,.4,0,Math.PI*2);c.stroke();c.fillStyle='#fff6c6';c.beginPath();c.arc(r*.4,-r*.2,2.5,0,Math.PI*2);c.fill();c.restore();}
export function drawDemolitionScenery(c,theme){c.save();const colors={forest:'#486a632f',city:'#66829b33',space:'#9393b329',volcano:'#a5796a29',ice:'#87afb433'};c.strokeStyle=colors[theme]||colors.city;c.fillStyle=c.strokeStyle;c.lineWidth=5;for(const x of [70,1380]){c.beginPath();c.moveTo(x,790);c.lineTo(x,320);c.lineTo(x+150,320);c.stroke();for(let y=350;y<790;y+=60){c.beginPath();c.moveTo(x-15,y);c.lineTo(x+15,y+50);c.moveTo(x+15,y);c.lineTo(x-15,y+50);c.stroke();}c.beginPath();c.moveTo(x+120,320);c.lineTo(x+120,450);c.stroke();c.strokeRect(x+105,450,30,20);}c.fillStyle='#1d3040';for(let x=650;x<1600;x+=115){c.fillRect(x,755,60,45);c.fillStyle='#8ba8a133';c.fillRect(x+6,763,48,4);c.fillStyle='#1d3040';}c.restore();}
